INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Array schneller als eine Liste bei zufälligen Zugriffen?', 2, '[{"text": "Ja", "correct": true, "because": "O(1) durch direkten Index"}, {"text": "Nein", "correct": false, "because": "Listen brauchen O(n)"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur nutze ich für eine LIFO-Aufgabe wie Rückgängig-Funktionen?', 3, '[{"text": "Stack", "correct": true, "because": "Last-In-First-Out passt perfekt"}, {"text": "Queue", "correct": false, "because": "FIFO ist ungeeignet"}, {"text": "Array", "correct": false, "because": "Keine LIFO-Unterstützung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen eignen sich für eine Warteschlange?', 5, '[{"text": "Queue", "correct": true, "because": "FIFO ist ideal"}, {"text": "Array", "correct": true, "because": "Kann als Ringpuffer genutzt werden"}, {"text": "Stack", "correct": false, "because": "LIFO passt nicht"}, {"text": "HashMap", "correct": false, "because": "Keine Reihenfolge"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arrays haben feste Größe. b) Listen sind immer dynamisch.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Arrays sind statisch, Listen flexibel"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl zwischen Stack und Queue für eine Aufgabe?', 4, '[{"text": "Reihenfolge der Elemente", "correct": false, "because": "Entscheidend für LIFO/FIFO"}, {"text": "Zugriffsmuster", "correct": false, "because": "Definiert die Struktur"}, {"text": "Sortierfähigkeit", "correct": true, "because": "Irrelevant für beide"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Stack auch FIFO unterstützen kann?', 2, '[{"text": "Nein", "correct": true, "because": "Stack ist strikt LIFO"}, {"text": "Ja", "correct": false, "because": "Das wäre eine Queue"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich, wenn ich Elemente am Ende schnell hinzufügen will?', 3, '[{"text": "ArrayList", "correct": true, "because": "O(1) amortisiert"}, {"text": "Array", "correct": false, "because": "O(n) bei voller Größe"}, {"text": "Stack", "correct": false, "because": "Nur Top-Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen helfen bei chronologischen Daten?', 5, '[{"text": "Queue", "correct": true, "because": "FIFO hält Reihenfolge"}, {"text": "Liste", "correct": true, "because": "Flexibel für Zugriffe"}, {"text": "Stack", "correct": false, "because": "LIFO kehrt Reihenfolge um"}, {"text": "HashSet", "correct": false, "because": "Keine Ordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Arrays sind kompakter als Listen. b) Stacks sind schneller als Queues. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Stacks und Queues sind gleich schnell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist kontextabhängig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Array für dynamische Daten unwichtig?', 4, '[{"text": "Feste Größe", "correct": false, "because": "Problem bei Änderungen"}, {"text": "Indexzugriff", "correct": false, "because": "Vorteil bleibt"}, {"text": "Sortiergeschwindigkeit", "correct": true, "because": "Dynamik zählt, nicht Sortierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Liste immer besser als ein Array?', 2, '[{"text": "Nein", "correct": true, "because": "Arrays sind bei Zugriffen schneller"}, {"text": "Ja", "correct": false, "because": "Listen nur bei Änderungen besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen erlauben schnelles Entfernen am Anfang?', 4, '[{"text": "Queue", "correct": true, "because": "O(1) für Dequeue"}, {"text": "LinkedList", "correct": true, "because": "O(1) am Kopf"}, {"text": "Array", "correct": false, "because": "O(n) wegen Verschiebung"}, {"text": "Stack", "correct": false, "because": "Nur Top-Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Stack nur für rekursive Aufgaben nützlich ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Undo oder Parsing geeignet"}, {"text": "Ja", "correct": false, "because": "Stack hat breitere Anwendungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur nutze ich für eine Aufgabe mit häufigem Einfügen in der Mitte?', 3, '[{"text": "LinkedList", "correct": true, "because": "O(1) bei bekanntem Knoten"}, {"text": "Array", "correct": false, "because": "O(n) wegen Verschiebung"}, {"text": "Queue", "correct": false, "because": "Nur Endzugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Queues sind für FIFO. b) Arrays können FIFO simulieren.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Arrays als Ringpuffer möglich"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen sind für eine Historie von Aktionen geeignet?', 5, '[{"text": "Stack", "correct": true, "because": "LIFO für Rückgängig"}, {"text": "Liste", "correct": true, "because": "Flexibel für Durchlauf"}, {"text": "Queue", "correct": false, "because": "FIFO nicht ideal"}, {"text": "Array", "correct": false, "because": "Statisch und unflexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Arrays für kleine Datenmengen?', 3, '[{"text": "Speicherbedarf", "correct": false, "because": "Wichtig bei Skalierung"}, {"text": "Zugriffsgeschwindigkeit", "correct": false, "because": "Kernvorteil"}, {"text": "Dynamische Anpassung", "correct": true, "because": "Bei kleinen Mengen sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit Stacks? Sind sie nur für Top-Zugriffe geeignet?', 3, '[{"text": "Ja", "correct": true, "because": "LIFO definiert Stack"}, {"text": "Nein", "correct": false, "because": "Andere Zugriffe unüblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Queue auch LIFO unterstützen kann?', 2, '[{"text": "Nein", "correct": true, "because": "Queue ist strikt FIFO"}, {"text": "Ja", "correct": false, "because": "Das wäre ein Stack"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich für eine Playlist mit zufälligem Zugriff?', 4, '[{"text": "ArrayList", "correct": true, "because": "O(1) Zugriff und dynamisch"}, {"text": "Queue", "correct": false, "because": "Nur sequenziell"}, {"text": "Stack", "correct": false, "because": "Nur Top-Zugriff"}]');
